 const activeTasks=data.tasks.filter(x=>!x.deleted&&!x.archived),activeNotes=data.notes.filter(x=>!x.deleted&&!x.archived),todays=activeTasks.filter(x=>x.date===today),done=todays.filter(x=>x.done).length,progress=todays.length?Math.round(done/todays.length*100):0,overdue=activeTasks.filter(x=>!x.done&&x.date<today),important=activeTasks.filter(x=>!x.done&&x.priority==='high');
 const cat=(id:string)=>data.categories.find(x=>x.id===id);const catName=(c:Category)=>fa?c.name:({work:'Work',personal:'Personal',study:'Learning',ideas:'Ideas'}[c.id]||c.name);
