 function copyNote(x:Note){const now=new Date().toISOString();update(d=>({...d,notes:[{...x,id:uid(),title:x.title+t(' (کپی)',' (copy)'),created:now,updated:now},...d.notes]}));notify(t('یادداشت کپی شد','Note duplicated'))}
 function reorder(target:string){const id=dragId.current;if(!id||id===target)return;update(d=>{const a=[...d.tasks];const from=a.findIndex(x=>x.id===id),to=a.findIndex(x=>x.id===target);if(from<0||to<0)return d;const [item]=a.splice(from,1);a.splice(to,0,item);return {...d,tasks:a}});dragId.current=''}
 useEffect(()=>{const listener=(e:KeyboardEvent)=>{if(e.key==='Escape'){setModal(null);setConfirm(null);setMenu(null);setMobile(false);setQuery('');return}if((e.target as HTMLElement).closest('input,textarea,select,[contenteditable="true"]')||e.ctrlKey||e.metaKey||e.altKey||modal)return;if(e.key==='/'){e.preventDefault();searchRef.current?.focus()}if(e.key.toLowerCase()==='t'){e.preventDefault();newTask()}if(e.key.toLowerCase()==='n'){e.preventDefault();newNote()}};window.addEventListener('keydown',listener);return()=>window.removeEventListener('keydown',listener)},[modal,today]);
 useEffect(()=>{if(!modal&&!confirm)return;const el=document.querySelector<HTMLElement>('.overlay:last-of-type .dialog');const prev=document.activeElement as HTMLElement;const timer=setTimeout(()=>el?.querySelector<HTMLElement>('input,button,textarea,[contenteditable]')?.focus(),60);const trap=(e:KeyboardEvent)=>{if(e.key!=='Tab'||!el)return;const list=[...el.querySelectorAll<HTMLElement>('button,input,select,textarea,[contenteditable],a[href]')].filter(x=>!x.hasAttribute('disabled')&&x.offsetParent!==null);if(!list.length)return;const first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}};document.addEventListener('keydown',trap);return()=>{clearTimeout(timer);document.removeEventListener('keydown',trap);prev?.focus()}},[modal,!!confirm]);
