 const statsCards=<div className="stats-grid">{[[t('کارهای امروز','Today’s tasks'),todays.length,CheckCheck,'purple',t('یک روز، فرصت‌های تازه','A new day, new possibilities')],[t('انجام‌شده','Completed'),done,CheckCircle2,'green',t('هر قدم کوچک ارزشمنده','Every little step counts')],[t('باقی‌مانده','Remaining'),todays.length-done,Clock,'orange',t('با تمرکز ادامه بده','Keep your focus')],[t('عقب‌افتاده','Overdue'),overdue.length,Flag,'rose',t('هنوز فرصت جبران هست','There’s still time')]].map(([label,value,Icon,color,sub],i)=>{const I=Icon as LucideIcon;return <button className="stat-card" key={String(label)} onClick={()=>{navigate('tasks');setView(['today','completed','today','overdue'][i]);if(i===2)setSearchType('uncompleted');else setSearchType('all')}}><div className="stat-head"><span>{String(label)}</span><div className={'stat-icon '+color}><I size={20}/></div></div><strong>{num(value as number)}</strong><p>{String(sub)}</p></button>})}</div>;
